    components = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] != 0 and not visited[i][j]:
                # BFS to collect the component
                stack = [(i, j)]
                visited[i][j] = True
                cells = []
                while stack:
                    x, y = stack.pop()
                    cells.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != 0 and not visited[nx][ny]:
                            visited[nx][ny] = True
                            stack.append((nx, ny))
                # bounding box of the component
                rows = [c[0] for c in cells]
                cols = [c[1] for c in cells]
                top, bottom = min(rows), max(rows)
                left, right = min(cols), max(cols)
                components.append((left, right, top, bottom))

    # ------------------------------------------------------------
    # identify the right‑most cluster
    # ------------------------------------------------------------
    rightmost_left = max(comp[0] for comp in components)

    # ------------------------------------------------------------
    # process clusters from left to right
    # ------------------------------------------------------------
